        // Compute val
        for (int i = 0; i < n; ++i) {
            if (s[i] == '?') {
                if (i == 0) {
                    t->val[i] = 0;
                } else {
                    t->val[i] = 1 - t->val[t->parent[i]];
                }
            } else {
                t->val[i] = s[i] == '1' ? 1 : 0;
            }
        }

        // Compute score
        int score = 0;
        for (int i = 1; i <= n; ++i) {
            if (t->is_leaf[i]) {
                int sum = 0;
                int prev = t->val[0];
                for (int j = 1; j < i; ++j) {
                    if (t->val[j] != prev) {
                        if (prev == 0) {
                            sum++;
                        } else {
                            sum--;
                        }
                        prev = t->val[j];
                    }
                }
                if (sum != 0) {
                    score++;
                }
            }
        }

        cout << score << "\n";
    }
    return 0;
}
